package local.thor.ffxiicompanion;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

import local.thor.ffxiicompanion.ReceiverState.FamilyState;
import local.thor.ffxiicompanion.ReceiverState.Transport;
import local.thor.ffxiicompanion.ReceiverState.View;

/**
 * Behaviour tests for the receiver model, driven by the synthetic fixtures in tests/fixtures
 * (generated by gen_fixtures.py). Times are a fake monotonic clock and fake file mtimes in ms.
 */
public final class ReceiverStateTest {
    static Path dir;
    static int passed;

    static void check(boolean condition, String what) {
        if (!condition) throw new AssertionError(what);
    }

    static String text(String name) throws Exception {
        return new String(Files.readAllBytes(dir.resolve(name + ".json")), StandardCharsets.UTF_8);
    }

    static Snapshot fx(String name, long mtime) throws Exception {
        Snapshot s = Snapshot.parse(text(name), mtime);
        check(s != null, "fixture parses: " + name);
        return s;
    }

    /** One poll with a single slot file present (the other slot missing). */
    static View poll(ReceiverState r, Snapshot s, long now) {
        return r.update(s, null, 0, true, now, now);
    }

    static void ok(String name) {
        passed++;
        System.out.println("PASS " + name);
    }

    public static void main(String[] args) throws Exception {
        dir = Paths.get(args.length > 0 ? args[0] : "tests/fixtures");

        { // Four members including a guest, all values present.
            ReceiverState r = new ReceiverState(true);
            View v = poll(r, fx("party_four_live", 1000), 1000);
            check(v.transport == Transport.LIVE, "transport live");
            check(v.partyFamily.state == FamilyState.LIVE, "party live");
            check(v.party.members.size() == 4, "four members");
            check(v.party.members.get(0).leader && "Vaan".equals(v.party.members.get(0).name), "leader first");
            check("guest".equals(v.party.members.get(3).role), "guest role kept");
            check(v.party.members.get(2).hp.cur == 905 && v.party.members.get(2).hp.max == 1980, "hp values");
            check(v.synthetic, "synthetic flagged");
            check(v.locationFamily.state == FamilyState.LIVE, "location live alongside party");
            ok("four_members_with_guest");
        }
        { // KO, missing MP and an impossible MP value (cur > max) stay unknown; nothing is clamped.
            ReceiverState r = new ReceiverState(true);
            View v = poll(r, fx("party_ko_missing_mp", 1000), 1000);
            Party.Member basch = v.party.members.get(1), penelo = v.party.members.get(2), guest = v.party.members.get(3);
            check(Boolean.TRUE.equals(basch.ko) && basch.hp.cur == 0, "KO flagged with 0 HP");
            check(v.party.members.get(0).ko == null, "no KO flag = unknown, not false");
            check(penelo.mp == null && !penelo.mpInvalid, "missing MP is unavailable");
            check(guest.mp == null && guest.mpInvalid, "cur > max MP is invalid, not clamped");
            ok("ko_missing_and_invalid_mp");
        }
        { // Party sampler 10 s behind while location stays fresh.
            ReceiverState r = new ReceiverState(true);
            View v = poll(r, fx("party_stale_location_fresh", 1000), 1000);
            check(v.transport == Transport.LIVE, "transport live");
            check(v.locationFamily.state == FamilyState.LIVE, "location fresh");
            check(v.partyFamily.state == FamilyState.STALE, "party stale");
            check(v.partyFamily.ageMs >= 10_000, "party age reported: " + v.partyFamily.ageMs);
            check(v.party != null, "last party sample still shown (as stale)");
            ok("stale_party_fresh_location");
        }
        { // Newest snapshot without a party block: the earlier sample goes stale, it is not shown as live.
            ReceiverState r = new ReceiverState(true);
            poll(r, fx("party_four_live", 1000), 1000);
            View v = poll(r, fx("location_only", 2000), 2000);
            check(v.partyFamily.state == FamilyState.STALE, "party stale when newest lacks it");
            check(v.locationFamily.state == FamilyState.LIVE, "location live");
            ok("party_missing_from_newest_snapshot");
        }
        { // More than four members: four shown, the rest counted.
            ReceiverState r = new ReceiverState(true);
            View v = poll(r, fx("party_five_members", 1000), 1000);
            check(v.party.members.size() == 4 && v.party.dropped == 1, "4 shown + 1 dropped");
            ok("overflow_beyond_four");
        }
        { // A live party block without the ffxii.party.v1 contract is ignored, even with capability "on".
            ReceiverState r = new ReceiverState(false);
            View v = poll(r, fx("party_unverified_live_shape", 1000), 1000);
            check(v.party == null && v.partyFamily.state == FamilyState.DISABLED, "unverified live party ignored");
            check(!v.synthetic, "not labelled synthetic");
            check(v.locationFamily.state == FamilyState.LIVE, "location still shown");
            ok("live_party_gate_closed");
        }
        { // 0.17.0: logger 0.5.9 party (contract, verified build, capability probe) is shown, flagged as probe.
            ReceiverState r = new ReceiverState(false);
            View v = poll(r, fx("party_logger_probe", 1000), 1000);
            check(v.partyFamily.state == FamilyState.LIVE && v.party != null && v.partyProbe, "logger party live (probe)");
            check(v.party.members.size() == 3 && v.party.members.get(0).hp.cur == 1200 && v.party.members.get(1).mp.cur == 60, "values");
            check("Member 13".equals(v.party.members.get(2).name) && v.party.members.get(2).ko == null, "unnamed ID labelled, KO unknown");
            check(!v.synthetic, "not synthetic");
            v = poll(new ReceiverState(false), fx("party_logger_not_ready", 1000), 1000);
            check(v.party == null && v.partyFamily.state == FamilyState.MISSING && "no save loaded".equals(v.partyFamily.reason), "not ready");
            v = poll(new ReceiverState(false), fx("party_logger_wrong_build", 1000), 1000);
            check(v.party == null && v.partyFamily.state == FamilyState.DISABLED, "unverified build ignored");
            ok("logger_party_probe_shown_only_on_verified_build");
        }
        { // End to end: the snapshot ThorCompanion.lua 0.5.9 wrote in test_party_family.py (real save_27 dump), if present.
            java.nio.file.Path lua = java.nio.file.Paths.get("tests/out/lua_party_snapshot.json");
            if (java.nio.file.Files.isRegularFile(lua)) {
                Snapshot s = Snapshot.parse(new String(java.nio.file.Files.readAllBytes(lua), java.nio.charset.StandardCharsets.UTF_8), 1000);
                check(s != null, "lua snapshot parses");
                View v = poll(new ReceiverState(false), s, 1000);
                check(v.partyFamily.state == FamilyState.LIVE && !v.partyProbe && v.party.members.size() == 4, "lua party live (verified, no check note): " + v.partyFamily.reason);
                check("Vaan".equals(v.party.members.get(0).name) && v.party.members.get(0).hp.cur == 2747 && v.party.members.get(3).mp.max == 339, "lua values");
                ok("lua_0_5_9_party_snapshot_end_to_end");
            }
        }
        { // Synthetic party data outside fixture mode is never shown.
            ReceiverState r = new ReceiverState(false);
            View v = poll(r, fx("party_four_live", 1000), 1000);
            check(v.party == null && v.partyFamily.state == FamilyState.DISABLED, "synthetic ignored in live mode");
            check(v.synthetic, "but the snapshot is still labelled synthetic");
            ok("synthetic_party_blocked_in_live_mode");
        }
        { // No party data at all: the strip says the feed is not available, not an error.
            ReceiverState r = new ReceiverState(false);
            View v = poll(r, fx("location_only", 1000), 1000);
            check(v.partyFamily.state == FamilyState.DISABLED && v.party == null, "party off");
            ok("no_party_feed");
        }
        { // Transport goes stale without new files; every family follows.
            ReceiverState r = new ReceiverState(true);
            Snapshot s = fx("party_four_live", 1000);
            poll(r, s, 1000);
            View v = poll(r, s, 1000 + ReceiverState.STALE_MS + 1000);
            check(v.transport == Transport.STALE, "transport stale");
            check(v.locationFamily.state == FamilyState.STALE, "location stale");
            check(v.partyFamily.state == FamilyState.STALE, "party stale");
            ok("transport_stale");
        }
        { // An old file seen on first start is aged by its mtime, not shown as live.
            ReceiverState r = new ReceiverState(true);
            View v = r.update(fx("location_only", 1000), null, 0, true, 50, 60_000);
            check(v.transport == Transport.STALE, "old file is stale on first sight");
            ok("old_file_on_first_start");
        }
        { // Session restart: seq drops to 1 in a newer file -> new session, map and party reset.
            ReceiverState r = new ReceiverState(true);
            poll(r, fx("party_four_live", 1000), 1000);
            View v = poll(r, fx("session2_first", 3000), 3000);
            check(v.session == 2, "session 2: " + v.session);
            check(v.location == null && v.locationFamily.state == FamilyState.MISSING, "old map not carried over");
            check(v.party == null, "old party not carried over");
            v = poll(r, fx("session2_with_map", 4000), 4000);
            check(v.session == 2 && v.locationFamily.state == FamilyState.LIVE, "new session map");
            ok("session_restart_resets");
        }
        { // Game closed: exit snapshot clears party, keeps location as last known; next run is a new session.
            ReceiverState r = new ReceiverState(true);
            poll(r, fx("party_four_live", 1000), 1000);
            View v = poll(r, fx("game_closed", 2000), 2000);
            check(v.transport == Transport.GAME_CLOSED, "game closed");
            check(v.party == null && v.partyFamily.state == FamilyState.CLOSED, "party cleared");
            check(v.locationFamily.state == FamilyState.CLOSED && v.location != null, "location last known");
            v = poll(r, fx("location_only", 9000), 9000);
            check(v.session == 2 && v.transport == Transport.LIVE, "run after exit = new session");
            ok("game_closed_then_new_run");
        }
        { // Receiver started after the game exited: last known area comes from the other slot's heartbeat.
            ReceiverState r = new ReceiverState(true);
            View v = r.update(fx("game_closed", 2000), fx("party_four_live", 1000), 0, true, 2000, 2000);
            check(v.transport == Transport.GAME_CLOSED, "closed");
            check(v.location != null && v.location.seq == 12, "last known map from same run");
            check(v.locationFamily.state == FamilyState.CLOSED && v.party == null, "closed families");
            // ...but not from a newer-seq file of another run.
            r = new ReceiverState(true);
            v = r.update(fx("session2_first", 2000), fx("party_four_live", 1000), 0, true, 2000, 2000);
            check(v.location == null, "older run's map not borrowed");
            ok("cold_start_after_exit_keeps_last_area");
        }
        { // A stale exit file in the other slot never beats the new run (file recency first).
            ReceiverState r = new ReceiverState(true);
            View v = r.update(fx("game_closed", 1000), fx("session2_first", 2000), 0, true, 2000, 2000);
            check(v.transport == Transport.LIVE && v.current.seq == 1, "new run selected over old exit");
            ok("old_exit_slot_ignored");
        }
        { // Malformed slots: skipped and counted; the good slot is used; all bad = no data.
            for (String bad : new String[] { "malformed_truncated", "malformed_wrong_version", "malformed_no_data" }) {
                check(Snapshot.parse(text(bad), 1000) == null, "rejects " + bad);
            }
            check(Snapshot.parse("", 1) == null && Snapshot.parse(null, 1) == null, "rejects empty");
            ReceiverState r = new ReceiverState(true);
            View v = r.update(null, null, 2, true, 1000, 1000);
            check(v.transport == Transport.NO_DATA && v.malformedReads == 2, "all malformed = no data");
            v = r.update(null, fx("location_only", 1000), 1, true, 1000, 1000);
            check(v.transport == Transport.LIVE && v.malformedReads == 1, "good slot used, bad counted");
            v = r.update(null, null, 2, true, 2000, 2000);
            check(v.transport == Transport.LIVE && v.current.seq == 20, "half-written pair keeps last good");
            ok("malformed_snapshots");
        }
        { // Disconnect/reconnect: files vanish -> NO SIGNAL with last state; same session resumes.
            ReceiverState r = new ReceiverState(true);
            poll(r, fx("party_four_live", 1000), 1000);
            View v = r.update(null, null, 0, false, 2000, 2000);
            check(v.transport == Transport.NO_SIGNAL, "no signal");
            check(v.locationFamily.state == FamilyState.STALE && v.partyFamily.state == FamilyState.STALE, "families stale");
            check(v.location != null, "last location kept");
            v = poll(r, fx("location_only", 5000), 5000);  // seq 20 > 12: same session continues
            check(v.transport == Transport.LIVE && v.session == 1, "reconnect same session");
            r.update(null, null, 0, false, 6000, 6000);
            v = poll(r, fx("session2_first", 9000), 9000);  // seq dropped: game restarted meanwhile
            check(v.session == 2 && v.location == null, "reconnect into a new session resets");
            ok("disconnect_reconnect");
        }
        { // Duplicate polls of the same file do not refresh freshness.
            ReceiverState r = new ReceiverState(true);
            Snapshot s = fx("location_only", 1000);
            poll(r, s, 1000);
            poll(r, fx("location_only", 1000), 4000);
            View v = poll(r, s, 1000 + ReceiverState.STALE_MS + 1);
            check(v.transport == Transport.STALE, "re-reading an unchanged file is not an update");
            ok("duplicate_not_refresh");
        }
        { // JSON reader edge cases used by the snapshot parser.
            check(Json.parse("{\"a\":[1,2.5,\"x\\u0041\",true,null]}") != null, "valid json");
            for (String bad : new String[] { "{", "{\"a\":}", "[1,]", "{\"a\":1}x", "\"\u0001\"", "01" }) {
                boolean threw = false;
                try { Json.parse(bad); } catch (IllegalArgumentException e) { threw = true; }
                check(threw, "rejects " + bad);
            }
            ok("json_reader_strict");
        }
        System.out.println(passed + " receiver behaviour tests passed");
    }
}
